              "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { firstValueFrom } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> 'rxjs'</span><span style=\"color:#E1E4E8\">;</span>",
              "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { ApplePayEventsEnum, Stripe } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe'</span><span style=\"color:#E1E4E8\">;</span>",
              "",
              "<span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#F97583\">  try</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#F97583\">    await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">isApplePayAvailable</span><span style=\"color:#E1E4E8\">();</span>",
              "<span style=\"color:#E1E4E8\">  } </span><span style=\"color:#F97583\">catch</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\">;</span>",
              "<span style=\"color:#E1E4E8\">  }</span>",
              "",
              "<span style=\"color:#E1E4E8\">  Stripe.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(ApplePayEventsEnum.Completed, () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'ApplePayEventsEnum.Completed'</span><span style=\"color:#E1E4E8\">);</span>",
              "<span style=\"color:#E1E4E8\">  });</span>",
              "",
              "<span style=\"color:#a0aab5\">  // Connect to your backend endpoint, and get paymentIntent.</span>",
              "<span style=\"color:#F97583\">  const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">paymentIntent</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> firstValueFrom</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">post</span><span style=\"color:#E1E4E8\">&lt;{</span>",
              "<span style=\"color:#FFAB70\">    paymentIntent</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span>",
              "<span style=\"color:#E1E4E8\">  }&gt;(environment.api </span><span style=\"color:#F97583\">+</span><span style=\"color:#9ECBFF\"> 'intent'</span><span style=\"color:#E1E4E8\">, {}));</span>",
              "",
              "<span style=\"color:#a0aab5\">  // Prepare Apple Pay</span>",
              "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">createApplePay</span><span style=\"color:#E1E4E8\">({</span>",
              "<span style=\"color:#E1E4E8\">    paymentIntentClientSecret: paymentIntent,</span>",
              "<span style=\"color:#E1E4E8\">    paymentSummaryItems: [{</span>",
              "<span style=\"color:#E1E4E8\">      label: </span><span style=\"color:#9ECBFF\">'Product Name'</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">      amount: </span><span style=\"color:#79B8FF\">1099.00</span>",
              "<span style=\"color:#E1E4E8\">    }],</span>",
              "<span style=\"color:#E1E4E8\">    merchantIdentifier: </span><span style=\"color:#9ECBFF\">'merchant.com.getcapacitor.stripe'</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">    countryCode: </span><span style=\"color:#9ECBFF\">'US'</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">    currency: </span><span style=\"color:#9ECBFF\">'USD'</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">  });</span>",
              "",
              "<span style=\"color:#a0aab5\">  // Present Apple Pay</span>",
              "<span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> result</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">presentApplePay</span><span style=\"color:#E1E4E8\">();</span>",
              "<span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (result.paymentResult </span><span style=\"color:#F97583\">===</span><span style=\"color:#E1E4E8\"> ApplePayEventsEnum.Completed) {</span>",
