              "<span style=\"color:#F97583\">const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">readers</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">discoverReaders</span><span style=\"color:#E1E4E8\">({</span>",
