              "",
              "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> reader</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> readers[</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">];</span>",
              "<span style=\"color:#F97583\">if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">reader) </span><span style=\"color:#F97583\">throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Tap to Pay is not available on this device'</span><span style=\"color:#E1E4E8\">);</span>",
